function formatHooks() {
  const out = [];
  const types = Object.keys(HOOK_FORMULAS);
  for (let i = 0; i < types.length; i++) {
    const type = types[i];
    out.push(type + ':');
    const arr = HOOK_FORMULAS[type];
    for (let j = 0; j < arr.length; j++) {
      const f = arr[j];
      out.push('  - [' + f.p + '] Template: ' + f.t + ' | Contoh: ' + f.e);
    }
  }
  return out.join('\n');
}

