function tryParse(s) {
  try { return JSON.parse(s); } catch(e) { return null; }
}

function repairHashtags(s) {
  // Fix bare hashtag missing leading quote inside array, e.g. , #Tag" or [ #Tag"
  return s.replace(/([\[,]\s*)#([^",\]\}]+)"/g, '$1"#$2"');
}

function repairAndParse(raw) {
  let s = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();

  let result = tryParse(s);
  if (Array.isArray(result)) return result;
  if (result && Array.isArray(result.plan)) return result.plan;
  if (result && Array.isArray(result.items)) return result.items;

  // Fix 1: stray single-quote at end of value
  let fixed = s.replace(/([\w!?.\)])'(\s*[,\n}\]])/g, '$1"$2');
  result = tryParse(fixed);
  if (Array.isArray(result)) return result;
  if (result && Array.isArray(result.plan)) return result.plan;

  // Fix 2: aggressive single-quote replace
  fixed = s.replace(/'(\s*[,\n}\]])/g, '"$1');
  fixed = fixed.replace(/([,\n{\[]\s*)'/g, '$1"');
  result = tryParse(fixed);
  if (Array.isArray(result)) return result;
  if (result && Array.isArray(result.plan)) return result.plan;

  // Fix 3: hashtag missing leading quote
  fixed = repairHashtags(s);
  result = tryParse(fixed);
  if (Array.isArray(result)) return result;
  if (result && Array.isArray(result.plan)) return result.plan;

  // Fix 4: extract array substring then apply all repairs
  const firstBracket = s.indexOf('[');
  const lastBracket = s.lastIndexOf(']');
  if (firstBracket !== -1 && lastBracket > firstBracket) {
    let inner = s.slice(firstBracket, lastBracket + 1);
    inner = repairHashtags(inner);
    inner = inner.replace(/([\w!?.\)])'(\s*[,\n}\]])/g, '$1"$2');
    result = tryParse(inner);
    if (Array.isArray(result)) return result;
  }

  // Fix 5: parse object-by-object, skip malformed ones
  if (firstBracket !== -1 && lastBracket > firstBracket) {
    const inner = s.slice(firstBracket + 1, lastBracket);
    const objects = [];
    let depth = 0, start = -1, inStr = false, esc = false;
    for (let i = 0; i < inner.length; i++) {
      const ch = inner[i];
      if (esc) { esc = false; continue; }
      if (ch === '\\') { esc = true; continue; }
      if (ch === '"') { inStr = !inStr; continue; }
      if (inStr) continue;
      if (ch === '{') { if (depth === 0) start = i; depth++; }
      else if (ch === '}') {
        depth--;
        if (depth === 0 && start !== -1) {
          let obj = inner.slice(start, i + 1);
          obj = repairHashtags(obj);
          obj = obj.replace(/([\w!?.\)])'(\s*[,\n}\]])/g, '$1"$2');
          const parsed = tryParse(obj);
          if (parsed) objects.push(parsed);
          start = -1;
        }
      }
    }
    if (objects.length > 0) return objects;
  }

  return [];
}

