function getOptimalPostTime(contentType, postDateStr) {
  const hours = PEAK_HOURS[contentType] || PEAK_HOURS.Entertain;
  const date = new Date(postDateStr);
  const dayOfWeek = date.getDay();
  const multiplier = DAY_MULTIPLIER[dayOfWeek] || 0;
  return hours[multiplier % hours.length];
}

