    let s = raw.trim();
    if(s.indexOf('{')===0 && s.lastIndexOf('}')===s.length-1) s = s.slice(1,-1);
    return s.split(',').map(function(t){return t.trim().replace(/^"|"$/g,'').replace(/\\"/g,'"');}).join(' ');
  }
  return '';
}

