  requests.push({ insertText: { location: { index: idx }, text: titleText } });
  requests.push({
    updateParagraphStyle: {
      range: { startIndex: idx, endIndex: idx + titleText.length },
      paragraphStyle: { namedStyleType: 'TITLE', alignment: 'CENTER' },
      fields: 'namedStyleType,alignment'
    }
  });
  idx += titleText.length;

  // 2. Section 1 Header
  const s1 = '1. Informasi Dasar\n';
  requests.push({ insertText: { location: { index: idx }, text: s1 } });
  requests.push({
    updateParagraphStyle: {
      range: { startIndex: idx, endIndex: idx + s1.length },
      paragraphStyle: { namedStyleType: 'HEADING_3' },
      fields: 'namedStyleType'
    }
  });
  idx += s1.length;

  // 3. Info lines
  const infoLines = [
    'Judul     : ' + (s.title || '-'),
    'Produk    : ' + productName,
    'Jenis     : ' + (s.content_type || '-'),
    'Goal      : ' + (s.goal || '-'),
    'Post Type : ' + (s.post_type || 'Video TikTok')
  ];
  const infoText = infoLines.join('\n') + '\n\n';
  requests.push({ insertText: { location: { index: idx }, text: infoText } });
  idx += infoText.length;

  // 4. Section 2 Header
  const s2 = '2. Alur Storyboard\n';
  requests.push({ insertText: { location: { index: idx }, text: s2 } });
  requests.push({
    updateParagraphStyle: {
      range: { startIndex: idx, endIndex: idx + s2.length },
      paragraphStyle: { namedStyleType: 'HEADING_3' },
      fields: 'namedStyleType'
    }
  });
  idx += s2.length;

  // 5. Empty table (header row + scene rows)
  const sceneCount = (s.storyboard || []).length;
  const numRows = sceneCount + 1;
  if (numRows >= 2) {
    requests.push({
      insertTable: { location: { index: idx }, rows: numRows, columns: 4 }
    });
  }

  return { json: {
    row_number: s.row_number,
    title: s.title || '',
    docTitle: 'MR. PLANNER — Script #' + s.row_number + ' — ' + (s.title || ''),
    docRequests: requests,
    storyboard: s.storyboard || []
  }};
});

