const docs = $input.all();
const splitItems = $('Split Scripts').all();

function buildRequestsForDoc(doc, storyboard) {
  let table = null;
  if (doc && doc.body && Array.isArray(doc.body.content)) {
    for (let i=0; i<doc.body.content.length; i++) {
      if (doc.body.content[i].table) { table = doc.body.content[i].table; break; }
    }
  }
  if (!table) return { requests: [], hasTable: false, cellCount: 0 };

  const headers = ['Durasi', 'Visual (Adegan)', 'Audio (Voiceover/Musik)', 'Text Over/Element'];
  const cellData = [headers];
  (storyboard || []).forEach(function(scene){
    cellData.push([
      scene.durasi || '',
      scene.visual || '',
      scene.audio || '',
      scene.text_overlay || ''
    ]);
  });

  const cellWrites = [];
  (table.tableRows || []).forEach(function(row, rIdx){
    (row.tableCells || []).forEach(function(cell, cIdx){
      if (rIdx >= cellData.length || cIdx >= cellData[rIdx].length) return;
      const text = cellData[rIdx][cIdx];
      if (!text) return;
      const para = cell.content && cell.content[0];
      if (!para) return;
      const startIndex = para.startIndex;
      if (typeof startIndex !== 'number') return;
      cellWrites.push({ startIndex: startIndex, text: text });
    });
  });

  cellWrites.sort(function(a,b){ return b.startIndex - a.startIndex; });
  const requests = cellWrites.map(function(w){
    return { insertText: { location: { index: w.startIndex }, text: w.text } };
  });
  return { requests: requests, hasTable: true, cellCount: cellWrites.length };
}

return docs.map(function(docItem, idx){
  const doc = docItem.json;
  const split = splitItems[idx] && splitItems[idx].json;
  const storyboard = split ? (split.storyboard || []) : [];
  const result = buildRequestsForDoc(doc, storyboard);
  return { json: result, pairedItem: { item: idx } };
});

